const upsertEffectPreset = `-- name: UpsertEffectPreset :one
INSERT INTO effect_presets (campaign_id, owner_character_id, name, slug, note, ends_on, rounds, mods_json)
VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)
ON CONFLICT (campaign_id, COALESCE(owner_character_id, 0), name) DO UPDATE SET
    slug = excluded.slug, note = excluded.note, ends_on = excluded.ends_on,
    rounds = excluded.rounds, mods_json = excluded.mods_json
RETURNING id, campaign_id, owner_character_id, name, slug, note, ends_on, rounds, mods_json, created_at
`

type UpsertEffectPresetParams struct {
	CampaignID int64
	Owner      sql.NullInt64
	Name       string
	Slug       string
	Note       string
	EndsOn     enum.EffectEnd
	Rounds     int64
	ModsJson   string
}

// A same-name save by the same owner overwrites.
func (q *Queries) UpsertEffectPreset(ctx context.Context, arg UpsertEffectPresetParams) (EffectPreset, error) {
	row := q.db.QueryRowContext(ctx, upsertEffectPreset,
		arg.CampaignID,
		arg.Owner,
		arg.Name,
		arg.Slug,
		arg.Note,
		arg.EndsOn,
		arg.Rounds,
		arg.ModsJson,
	)
	var i EffectPreset
	err := row.Scan(
		&i.ID,
		&i.CampaignID,
		&i.OwnerCharacterID,
		&i.Name,
		&i.Slug,
		&i.Note,
		&i.EndsOn,
		&i.Rounds,
		&i.ModsJson,
		&i.CreatedAt,
	)
	return i, err
}
